            c=str(c)
            if c==prev: run+=1
            else: 
                mx=max(mx,run); run=1; prev=c
    mx=max(mx,run)
    if mx>=3:
        print(f'{t} steps={r[\"agent\"][\"steps\"]} max_identical_asst_run={mx}')
